// SINGLE SOURCE OF TRUTH. The website and the chat AI both read this file.
// To add a recipe: copy one block, change the id, and drop pics/<id>.jpg in the pics folder.
// level: 1 easy, 2 medium, 3 hard.  type: meal | snack | drink.
// aka = other names people might type (the chat uses these to find the recipe).
export const RECIPES = [
// ---------- EASY ----------
{ id:"ugali-mayai", country:"Kenyan", name:"Ugali Mayai", aka:["ugali mayai","ugali na mayai","ugali and eggs","eggs and ugali","ugali eggs"], level:1, type:"meal", time:"25 min", serves:2,
  ing:["2 cups maize flour","3 cups water","4 eggs","1 onion, chopped","2 tomatoes, chopped","3 tbsp oil","Salt, fresh coriander"],
  steps:["Boil the 3 cups of water. Add a handful of flour and stir into a thin porridge. Simmer 2 minutes.","Add the rest of the flour in batches, pressing and turning with a wooden spoon until it is stiff. Cover on low heat for 3 minutes, then press out lumps.","In another pan, fry the onion in oil until soft and golden.","Add tomatoes and a pinch of salt. Cook until they become a thick sauce.","Crack in the eggs and stir gently until just set. Sprinkle coriander.","Shape the ugali in a bowl, flip onto a plate and serve with the eggs."],
  tip:"Take the eggs off the heat while they still look a little wet. They keep cooking on the plate." },
{ id:"ugali-maziwa-mala", country:"Kenyan", name:"Ugali na Maziwa Mala", aka:["maziwa mala","mala with ugali","ugali na mala","ugali maziwa lala","maziwa lala","ugali and mala","ugali mala","ugali na maziwa"], level:1, type:"meal", time:"20 min", serves:2,
  ing:["2 cups maize flour","3 cups water","2 cups cold maziwa mala (fermented milk)","Pinch of salt (optional)"],
  steps:["Boil the water. Stir in a handful of flour to make a thin porridge.","Add the remaining flour in batches, pressing with a wooden spoon until stiff. Cover on low heat for 3 minutes.","Press out any lumps and shape the ugali in a wet bowl.","Chill the mala well and shake or stir it until smooth. Pour into cups or bowls.","Break off small pieces of ugali, roll them in your hand and dip them into the cold mala."],
  tip:"Hot ugali and ice-cold mala is the whole point. Do not warm the mala." },
{ id:"mayai-pori", country:"Kenyan", name:"Mayai Pori", aka:["mayai pori","scrambled eggs","kenyan scrambled eggs","egg scramble"], level:1, type:"meal", time:"10 min", serves:2,
  ing:["4 eggs","1 small onion, finely chopped","1 tomato, chopped","2 tbsp oil","Salt and pepper","Fresh coriander"],
  steps:["Heat the oil and fry the onion until soft, about 2 minutes.","Add the tomato and a pinch of salt. Cook until soft and saucy.","Beat the eggs in a cup and pour them in. Lower the heat.","Stir slowly until the eggs are set but still soft.","Finish with pepper and coriander. Serve with bread, chapati or ugali."],
  tip:"Low heat gives soft, creamy mayai pori. High heat makes it dry." },
{ id:"sukuma-wiki", country:"Kenyan", name:"Sukuma Wiki", aka:["sukuma wiki","sukuma","kale","collard greens"], level:1, type:"meal", time:"15 min", serves:3,
  ing:["1 large bunch of sukuma (kale), sliced thin","1 onion, chopped","2 tomatoes, chopped","3 tbsp oil","Salt","Optional: a little water, beef cubes"],
  steps:["Wash the sukuma and slice it thin. Remove thick stems.","Fry the onion in oil until golden.","Add the tomatoes and cook down to a paste.","Add the sukuma and salt. Stir well.","Cook 5 to 8 minutes, covered, stirring now and then. Add 2 tbsp water only if it sticks."],
  tip:"Do not overcook. It should still be bright green. Slice thin so it cooks fast." },
{ id:"kachumbari", country:"Kenyan", name:"Kachumbari", aka:["kachumbari","tomato onion salad","kenyan salsa"], level:1, type:"snack", time:"10 min", serves:4,
  ing:["3 ripe tomatoes","1 red onion","1 handful fresh coriander","1 green chili (optional)","Juice of half a lemon","Salt"],
  steps:["Slice the onion thin and soak it in cold water for 5 minutes. This removes the harsh bite.","Drain the onion and squeeze dry.","Chop the tomatoes, coriander and chili.","Mix everything with lemon juice and salt.","Serve straight away."],
  tip:"Salt only just before serving, or the tomatoes turn watery." },
{ id:"chai-ya-maziwa", country:"Kenyan", name:"Chai ya Maziwa", aka:["chai ya maziwa","kenyan tea","chai","milk tea","tea"], level:1, type:"drink", time:"10 min", serves:2,
  ing:["1 cup water","1 cup full-cream milk","2 tsp tea leaves (majani)","2 to 4 tsp sugar","Optional: crushed ginger or a cardamom pod"],
  steps:["Boil the water together with the tea leaves (and ginger or cardamom if using) for 2 minutes.","Add the milk and bring back to a gentle boil.","Simmer 3 to 4 minutes until the tea turns a deep golden brown. Watch it so it does not boil over.","Strain into cups and add sugar to taste."],
  tip:"Boiling the milk with the tea leaves, not after, gives the strong rich flavor." },
{ id:"indomie-mayai", country:"Kenyan", name:"Indomie Special (with Egg)", aka:["indomie","indomie mayai","indomie with egg","noodles","instant noodles","indomie special"], level:1, type:"meal", time:"10 min", serves:1,
  ing:["1 packet Indomie","1 egg","1 small tomato, chopped","Pinch of chopped onion","1 tsp oil","Optional: 1 smokie or fresh coriander"],
  steps:["Boil water and cook the noodles for 2 to 3 minutes. Drain, keeping 2 tbsp of the water.","Return noodles to the pot with the reserved water. Add the seasoning sachets and stir well.","In a small pan, heat the oil and fry the onion and tomato for 2 minutes. Push to the side.","Fry the egg sunny-side up or scramble it.","Pile the noodles in a bowl and top with the tomato and egg. Add sliced smokie or coriander if you have them."],
  tip:"Draining most of the water makes it saucy and flavorful instead of soupy." },
{ id:"smokie-pasua", country:"Kenyan", name:"Smokie Pasua", aka:["smokie pasua","smokie","smokies","smokie kachumbari","smokie and kachumbari","sausage kachumbari"], level:1, type:"snack", time:"10 min", serves:2,
  ing:["4 smokies (sausages)","1 batch kachumbari (see recipe)","Tomato ketchup or chili sauce","1 tsp oil"],
  steps:["Make the kachumbari: chop tomato, onion and coriander and mix with a little lemon and salt.","Slit each smokie lengthwise down the middle (that is the pasua).","Heat the oil and fry the smokies, cut-side down first, until browned.","Fill the slit with kachumbari.","Add a squeeze of ketchup or chili sauce and eat while hot."],
  tip:"Fry cut-side down first so the smokie opens up and holds more kachumbari." },
{ id:"ice-pops", country:"Kenyan", name:"Juice Ice Pops (Cola or Fruit)", aka:["ice pops","ice pop","ice lolly","ice lollies","ice lollipop","freezer pops","ice block","ice blocks","cola pops","cola ice pops","juice pops"], level:1, type:"snack", time:"10 min + 4 hrs freezing", serves:6,
  ing:["2 cups juice or cola (or cordial mixed a bit sweeter than normal)","Small plastic bags or small cups","Rubber bands or string","Optional: ice-cream sticks, a few fruit pieces"],
  steps:["Pour the juice or cola into small bags, filling about three-quarters.","Squeeze out the air and tie tightly. If using cups, add a stick after 1 hour of freezing so it stands upright.","Lay the bags flat in the freezer so they freeze in an even shape.","Freeze for at least 4 hours.","To eat, bite or snip a corner of the bag and suck. Peel the bag off cups by dipping briefly in warm water."],
  tip:"Make the juice sweeter than you would normally drink it. Freezing dulls sweetness. Cola pops work best flat, with the fizz gone." },
{ id:"cola-float", country:"Kenyan", name:"Cola Float", aka:["cola float","soda float","coke float","cola ice cream","float","juice cola","juice and cola","fanta float"], level:1, type:"drink", time:"5 min", serves:1,
  ing:["1 cup very cold cola (or any soda)","2 scoops vanilla ice cream","Tall glass","Optional: a splash of juice or a straw and long spoon"],
  steps:["Chill the soda and the glass.","Put 2 scoops of ice cream in the glass.","Pour the soda slowly down the side, so it does not foam over.","Serve right away with a straw and a long spoon."],
  tip:"Pour slowly. A fast pour makes a mountain of foam and a flat drink." },
{ id:"passion-juice", country:"Kenyan", name:"Fresh Passion Juice", aka:["passion juice","passion fruit juice","fresh juice","juice","maji ya pasheni","passion"], level:1, type:"drink", time:"10 min", serves:4,
  ing:["8 ripe passion fruits","4 cups cold water","4 to 6 tbsp sugar","Ice cubes"],
  steps:["Cut the fruits in half and scoop the pulp into a jug.","Add the water and sugar and stir until the sugar dissolves.","For a smoother juice, blend for 5 seconds on pulse, then strain. Do not over-blend, it crushes the seeds.","Taste and add sugar or water as needed.","Serve over ice. Chill leftovers and drink within 2 days."],
  tip:"Wrinkly passion fruits are the sweetest. Smooth ones are not ripe yet." },
{ id:"mahindi-choma", country:"Kenyan", name:"Mahindi Choma", aka:["mahindi choma","roasted maize","roast maize","roasted corn","corn on the cob","mahindi"], level:1, type:"snack", time:"25 min", serves:3,
  ing:["3 fresh maize cobs, husk removed","1 lemon, halved","2 tbsp salt","1 tsp chili powder"],
  steps:["Light the charcoal and wait until the flames die and the coals are glowing.","Place the cobs on the grill and turn every 3 minutes.","Roast 15 to 20 minutes until the kernels are golden with dark spots.","Mix the salt and chili powder on a plate.","Dip the cut side of the lemon in the mix and rub it over the hot cobs."],
  tip:"The lemon-salt-chili rub is what makes it taste like the street version. Do it while the cobs are hot." },
// ---------- MEDIUM ----------
{ id:"mandazi-ngumu", country:"Kenyan", name:"Mandazi Ngumu", aka:["mandazi ngumu","ngumu","hard mandazi","crunchy mandazi","firm mandazi"], level:2, type:"snack", time:"45 min", serves:6,
  ing:["3 cups flour","1/3 cup sugar","2 tsp baking powder","1 tsp ground cardamom","3/4 cup water or coconut milk","2 tbsp oil","Oil for deep frying"],
  steps:["Mix the flour, sugar, baking powder and cardamom.","Rub in 2 tbsp oil. Add the water slowly and knead into a stiff dough. It should be firmer than soft mandazi.","Rest the dough for 15 minutes.","Roll out thin, about 5 mm. Cut into triangles or squares.","Fry in medium-hot oil, turning often, until deep golden and crisp, about 4 to 5 minutes.","Drain and cool. They harden as they cool and keep for days."],
  tip:"Less liquid and thinner rolling gives the firm, crunchy ngumu texture. Perfect for dunking in tea." },
{ id:"mandazi", country:"Kenyan", name:"Mandazi", aka:["mandazi","soft mandazi","maandazi","mandasi"], level:2, type:"snack", time:"1 hr", serves:6,
  ing:["3 cups flour","1/2 cup sugar","2 tsp baking powder","1 tsp ground cardamom","1 egg","3/4 cup warm milk or coconut milk","2 tbsp oil","Oil for deep frying"],
  steps:["Mix the flour, sugar, baking powder and cardamom in a bowl.","Beat the egg into the warm milk, add the 2 tbsp oil, and pour into the flour.","Knead for 5 minutes into a soft, smooth dough.","Cover and rest 30 minutes.","Roll about 1 cm thick and cut into triangles.","Fry in medium-hot oil, 2 minutes each side, until puffed and golden. Drain on paper."],
  tip:"If the oil is too hot, mandazi brown outside and stay raw inside. Drop a bit of dough in: it should rise slowly and sizzle." },
{ id:"mandazi-ndizi", country:"Kenyan", name:"Mandazi ya Ndizi (Banana Mandazi)", aka:["mandazi ndizi","mandazi ya ndizi","banana mandazi","mandizi","mandazi mandizi","ndizi mandazi"], level:2, type:"snack", time:"50 min", serves:6,
  ing:["3 very ripe bananas, mashed","2 1/2 cups flour","1/4 cup sugar","2 tsp baking powder","1 tsp cardamom","A little milk if needed","Oil for deep frying"],
  steps:["Mash the bananas until completely smooth.","Mix the flour, sugar, baking powder and cardamom, then stir in the bananas.","Add a splash of milk only if the dough is dry. It should be soft but not sticky.","Rest 20 minutes.","Roll 1 cm thick, cut into shapes.","Fry in medium oil until golden on both sides."],
  tip:"The riper the bananas, the sweeter the mandazi. Black-spotted ones are ideal." },
{ id:"mandazi-pops", country:"Kenyan", name:"Mandazi Pops (Mandazi Lollipops)", aka:["mandazi pops","mandazi lollipop","mandazi lollipops","mandazi on a stick","lollipop mandazi","mandazi pop"], level:2, type:"snack", time:"1 hr", serves:8,
  ing:["1 batch mandazi dough (see Mandazi)","Ice-cream or wooden skewer sticks","Oil for deep frying","1/2 cup cinnamon sugar, or 100 g melted chocolate"],
  steps:["Make the mandazi dough and rest it 30 minutes.","Roll the dough into walnut-sized balls.","Fry in medium oil for 3 to 4 minutes, turning, until evenly golden. Drain and cool a little.","Push a stick into each ball.","Roll in cinnamon sugar, or dip in melted chocolate.","Stand them in a glass to set."],
  tip:"A fun twist on mandazi, not a traditional dish. Let the balls cool a bit before pushing the sticks in so they do not split." },
{ id:"githeri", country:"Kenyan", name:"Githeri", aka:["githeri","maize and beans","muthokoi"], level:2, type:"meal", time:"2 hrs 30 min (+ overnight soak)", serves:5,
  ing:["1 cup dried maize","1 cup dried beans (rosecoco or kidney)","1 onion","2 tomatoes","1 carrot, diced","2 tbsp oil","Salt","Optional: curry powder, potatoes"],
  steps:["Soak the maize and beans overnight in plenty of water.","Drain, add fresh water and boil for 1.5 to 2 hours until soft. Top up the water if it dries out. A pressure cooker cuts this to about 40 minutes.","Fry the onion in oil until golden. Add the tomatoes and cook down.","Add the carrot, salt and curry powder if using.","Add the boiled maize and beans with a little of their water.","Simmer 15 minutes until thick and flavorful."],
  tip:"Never add salt while boiling the beans. It makes them tough. Add it after they soften." },
{ id:"chapati", country:"Kenyan", name:"Chapati", aka:["chapati","chapatis","chapo","soft chapati","layered chapati"], level:2, type:"meal", time:"1 hr 15 min", serves:6,
  ing:["3 cups flour","1 tsp salt","1 tbsp sugar","1 cup warm water","4 tbsp oil, plus more for cooking"],
  steps:["Mix the flour, salt and sugar. Add 2 tbsp oil and the warm water gradually.","Knead for 10 minutes until smooth and soft. Rest 30 minutes.","Divide into 8 balls. Roll each into a thin circle and brush with oil.","Roll the circle up into a long rope, then coil it into a snail shape. Tuck the end under. Rest 15 minutes.","Roll each coil flat into a circle.","Cook on a hot dry pan 30 seconds, flip, brush with oil, flip again until golden with brown spots. Press with a cloth to keep it soft."],
  tip:"The rope-and-coil step makes the layers. Do not skip the rest, or the chapati will be tough." },
{ id:"wali-wa-nazi", country:"Kenyan", name:"Wali wa Nazi (Coconut Rice)", aka:["wali wa nazi","coconut rice","wali nazi","wali"], cat:"rice", level:2, type:"meal", time:"35 min", serves:4,
  ing:["2 cups rice (pishori or basmati)","2 cups thick coconut milk","1 1/2 cups water","1 tsp salt","Optional: 1 cardamom pod"],
  steps:["Rinse the rice until the water runs clear.","In a pot, bring the coconut milk, water, salt and cardamom to a gentle boil. Do not boil hard or it will split.","Add the rice and stir once.","Cover and cook on the lowest heat for 15 to 20 minutes.","Turn off the heat and rest, covered, for 10 minutes.","Fluff with a fork and serve."],
  tip:"Use thick first-press coconut milk for the best flavor. Do not lift the lid while it cooks." },
{ id:"maharagwe-ya-nazi", country:"Kenyan", name:"Maharagwe ya Nazi (Coconut Beans)", aka:["maharagwe ya nazi","coconut beans","maharagwe","beans in coconut"], level:2, type:"meal", time:"40 min (with cooked beans)", serves:4,
  ing:["2 cups cooked beans","1 onion, chopped","2 tomatoes, chopped","2 cloves garlic","1 tsp curry powder or turmeric","1 cup coconut milk","2 tbsp oil","Salt, fresh coriander"],
  steps:["If starting from dry beans, soak overnight and boil 1 to 1.5 hours until soft.","Fry the onion and garlic in oil until golden.","Add the tomatoes and curry powder. Cook until soft and thick.","Add the beans and a pinch of salt. Stir.","Pour in the coconut milk and simmer 15 minutes until creamy and thick.","Top with coriander. Serve with wali wa nazi or chapati."],
  tip:"Mash a few beans against the side of the pot to make the sauce thicker and creamier." },
{ id:"beef-stew", country:"Kenyan", name:"Beef Stew", aka:["beef stew","stew","nyama stew"], level:2, type:"meal", time:"1 hr 30 min", serves:4,
  ing:["500 g beef, cubed","2 onions","3 tomatoes","2 cloves garlic","1 carrot, diced","1 tbsp tomato paste","3 tbsp oil","Salt, coriander"],
  steps:["Boil the beef in water with a pinch of salt for 45 to 60 minutes until nearly tender. Keep the stock.","Heat the oil and fry the onions until golden brown.","Add garlic, then the tomatoes and tomato paste. Cook until it becomes a thick sauce.","Add the beef, carrot and 1 cup of the stock.","Simmer 20 minutes until the sauce thickens and the beef is soft.","Add coriander and adjust salt. Serve with ugali, rice or chapati."],
  tip:"Brown the onions properly. Deep golden onions give the stew its rich flavor." },
{ id:"mukimo", country:"Kenyan", name:"Mukimo", aka:["mukimo","irio","mashed potatoes and greens"], level:2, type:"meal", time:"50 min", serves:4,
  ing:["5 potatoes, peeled","1 cup green peas","1 cup boiled maize or githeri","2 cups pumpkin leaves, spinach or kale, chopped","1 onion, chopped","2 tbsp oil or butter","Salt"],
  steps:["Boil the potatoes in salted water until soft, about 20 minutes. Drain.","In another pot, boil the peas until soft. Add the maize to warm it.","Fry the onion in oil until soft. Add the chopped greens and cook 3 minutes.","Add the peas and maize to the greens.","Add the potatoes and mash everything together until mixed and mostly smooth.","Serve hot with stew or nyama choma."],
  tip:"Mash while the potatoes are still hot. They go gluey once they cool." },
// ---------- HARD ----------
{ id:"pilau", country:"Kenyan", name:"Pilau", aka:["pilau","kenyan pilau","pilau rice"], cat:"rice", level:3, type:"meal", time:"1 hr 30 min", serves:5,
  ing:["500 g beef, cubed","2 cups rice (pishori)","3 onions, sliced","4 cloves garlic, 1 tbsp ginger","2 tbsp pilau masala","4 cups beef stock","1/2 cup oil","2 potatoes, quartered (optional)","Salt"],
  steps:["Boil the beef with salt until tender, about 45 minutes. Keep 4 cups of the stock.","In a heavy pot, heat the oil and cook the onions slowly, about 15 minutes, until deep brown. Do not rush this.","Add garlic and ginger. Cook 1 minute.","Add the pilau masala and stir 1 minute until fragrant. Add the beef and potatoes and coat well.","Add the washed rice and stir for 1 minute.","Pour in the hot stock (about 2 parts stock to 1 part rice). Add salt, stir once, cover and cook on the lowest heat for 20 minutes.","Rest 10 minutes, fluff with a fork and serve with kachumbari."],
  tip:"The brown onions are the secret. That slow caramelizing gives pilau its color and flavor." },
{ id:"nyama-choma", country:"Kenyan", name:"Nyama Choma", aka:["nyama choma","roast meat","grilled goat","roasted goat","barbecue","bbq","choma"], level:3, type:"meal", time:"1 hr 30 min", serves:4,
  ing:["1 kg goat or beef ribs, in large pieces","Salt","2 lemons","Optional: 2 cloves crushed garlic","Charcoal","Kachumbari and ugali to serve"],
  steps:["Light the charcoal and wait for glowing coals with no flames.","Rub the meat with salt (and garlic if you like). Keep it simple.","Place the meat on the grill over medium heat, not directly over blazing coals.","Turn every 5 to 7 minutes. Brush with salted water or lemon to keep it moist.","Cook 45 to 60 minutes for beef, longer for goat, until well browned and tender when cut.","Rest 5 minutes, chop into pieces and serve with kachumbari, ugali and lemon."],
  tip:"Patience is the recipe. Slow, even heat gives tender nyama choma. Fast, flaring heat gives burnt outside, raw inside." },
{ id:"kuku-kienyeji", country:"Kenyan", name:"Kuku Kienyeji Stew", aka:["kuku kienyeji","kienyeji chicken","kuku","chicken stew","village chicken","free range chicken"], level:3, type:"meal", time:"1 hr 45 min", serves:5,
  ing:["1 whole kienyeji (free-range) chicken, cut up","2 onions","4 tomatoes","3 cloves garlic, 1 tbsp ginger","1 tbsp curry powder","1/3 cup oil","Salt, coriander"],
  steps:["Put the chicken in a pot with water, salt and ginger. Boil 40 to 50 minutes. Kienyeji is tough and needs this first.","Remove the chicken and keep the stock. Fry the chicken pieces in oil until browned. Set aside.","In the same oil, fry the onions until golden. Add the garlic and curry powder.","Add the tomatoes and cook down to a thick paste.","Return the chicken with 1 cup of stock.","Simmer 30 minutes until the sauce is thick and the meat is tender. Add coriander and serve with ugali."],
  tip:"Do not skip the boil, or the meat stays chewy. The reserved stock also adds a lot of flavor to the sauce." },
{ id:"samosa", country:"Kenyan", name:"Samosa", aka:["samosa","samosas","beef samosa","meat samosa"], level:3, type:"snack", time:"1 hr 30 min", serves:6,
  ing:["250 g beef mince","1 onion, finely chopped","2 cloves garlic, 1 tsp ginger","1 tsp cumin, 1 tsp coriander powder","1 green chili, chopped","Handful of chopped coriander","Ready-made samosa pastry strips (or spring roll sheets)","Flour paste (2 tbsp flour + 2 tbsp water)","Oil for frying"],
  steps:["Fry the onion, garlic and ginger in a little oil for 3 minutes.","Add the mince and cook until browned and dry. Add the spices, chili and salt. Cook until very dry.","Stir in the coriander and cool completely.","Fold a pastry strip into a cone. Fill with 1 heaped tablespoon of mince.","Fold over to make a triangle, tracing along the strip. Seal the final edge with flour paste.","Deep fry in medium-hot oil, 3 to 4 minutes, until golden and crisp.","Drain and serve hot."],
  tip:"The filling must be dry and cool. Wet filling makes the pastry soggy and burst while frying." },
{ id:"biryani", country:"Kenyan", name:"Biryani", aka:["biryani","chicken biryani","beef biryani","kenyan biryani"], cat:"rice", level:3, type:"meal", time:"2 hrs", serves:6,
  ing:["1 kg chicken or beef, cut up","1 cup plain yoghurt","2 tbsp ginger-garlic paste","2 tbsp biryani masala","3 cups basmati rice","4 onions, thinly sliced","3 potatoes, halved","Whole spices: 4 cloves, 2 cinnamon sticks, 4 cardamom pods","1/2 tsp turmeric","1/2 cup oil","Salt"],
  steps:["Marinate the meat in yoghurt, ginger-garlic paste, masala and salt for at least 1 hour.","Fry the sliced onions in oil until dark golden and crisp. Set half aside for layering.","In the same pot, fry the potatoes briefly. Add the marinated meat and cook on medium heat for 20 minutes.","Meanwhile, boil the rice in salted water with the whole spices until 70% cooked. Drain.","Layer rice over the meat. Top with the reserved onions and turmeric dissolved in 2 tbsp warm water.","Cover tightly and cook on the lowest heat for 30 minutes.","Rest 10 minutes. Gently mix from the bottom and serve with kachumbari."],
  tip:"Par-cook the rice only to 70%. It finishes steaming in the pot. Fully cooked rice turns mushy." },
// ---------- RICE ----------
{ id:"jollof-rice", country:"Nigerian", name:"Jollof Rice", aka:["jollof rice","jollof","party jollof","nigerian jollof"], cat:"rice", level:3, type:"meal", time:"70 min", serves:4,
  ing:["3 cups long-grain parboiled rice","5 large tomatoes","3 red bell peppers","2 scotch bonnet peppers (to taste)","2 onions","1/2 cup oil","3 tbsp tomato paste","2 cups chicken or beef stock","1 tsp thyme","1 tsp curry powder","2 bay leaves","Salt and stock cubes"],
  steps:["Blend the tomatoes, bell peppers, scotch bonnet and 1 onion. Boil the mixture in a pot for 15 to 20 minutes until the water dries and it thickens.","In a big pot, fry 1 sliced onion in the oil until soft. Add the tomato paste and fry 3 minutes.","Add the thick pepper mix. Fry 15 minutes, stirring, until the oil floats on top and the sour smell is gone.","Add the stock, thyme, curry, bay leaves, salt and stock cubes. Taste it, it should be slightly too salty because the rice will absorb it.","Wash the rice and add it. Stir once. The liquid should only just reach the top of the rice.","Cover with foil, then the lid. Cook on the lowest heat for 30 minutes without stirring. Check, add a splash of water if the rice is still hard, and cook 10 more minutes.","Mix gently from the bottom and serve."],
  tip:"Boil the pepper mix dry first. Watery base makes soggy jollof. A little burnt bottom gives the smoky party taste." },
{ id:"fried-rice", country:"Nigerian", name:"Fried Rice", aka:["fried rice","nigerian fried rice","veggie rice"], cat:"rice", level:2, type:"meal", time:"45 min", serves:4,
  ing:["3 cups long-grain parboiled rice","2 carrots, diced small","1 cup green beans, chopped","1/2 cup green peas","1/2 cup sweet corn","1 red bell pepper, diced","3 spring onions, chopped","1 onion, chopped","1/3 cup oil","2 tbsp soy sauce","1 tsp curry powder","1 tsp thyme","1/2 tsp turmeric","Stock cubes and salt","Optional: diced liver, shrimps or sausage"],
  steps:["Boil the rice with turmeric, salt and a stock cube until just tender. Drain and rinse with warm water so the grains separate. Let it dry out.","Boil the carrots, green beans and peas for 3 minutes. Drain.","Heat the oil and fry the onion for 2 minutes. Add liver, shrimps or sausage if using and cook through.","Add the vegetables, curry, thyme and soy sauce. Stir-fry on high heat for 3 minutes.","Add the rice and spring onions. Toss on high heat for 3 to 5 minutes until everything is hot and mixed.","Taste for salt and serve."],
  tip:"Use cooled, dry rice. Warm sticky rice turns into mush when you stir-fry it." },
{ id:"white-rice", country:"Nigerian", name:"White Rice", aka:["white rice","plain rice","boiled rice","steamed rice"], cat:"rice", level:1, type:"meal", time:"25 min", serves:4,
  ing:["3 cups long-grain parboiled rice","Plenty of water","1 tsp salt","Optional: 1 tbsp oil"],
  steps:["Wash the rice in cold water 3 or 4 times until the water is almost clear.","Boil a big pot of water with the salt.","Add the rice and stir once. Boil on medium heat for 12 to 15 minutes until soft with a tiny bite.","Drain in a sieve and rinse with hot water to remove extra starch.","Return to the pot, cover and steam on the lowest heat for 5 minutes.","Fluff with a fork and serve with stew, soup or sauce."],
  tip:"Boiling in lots of water and draining like pasta gives loose, separate grains every time." },
// ---------- SOUPS ----------
{ id:"ewedu-gbegiri", country:"Nigerian", name:"Ewedu and Gbegiri", aka:["ewedu","gbegiri","ewedu and gbegiri","abula","ewedu soup","mrenda soup"], cat:"soup", level:3, type:"meal", time:"75 min", serves:4,
  ing:["Gbegiri: 1.5 cups brown beans (peeled), 1/4 cup palm oil, 1 small onion, 1 scotch bonnet, salt and stock cube","Ewedu: 2 bunches ewedu leaves (jute leaves), 1 tbsp locust beans (iru), pinch of baking soda, salt","Serve with: stew sauce (see recipe) and amala"],
  steps:["Gbegiri: soak the beans and rub off the skins. Boil with the onion for 40 minutes until very soft.","Blend the beans smooth with some of the cooking water. Return to the pot.","Add palm oil, blended scotch bonnet, salt and stock cube. Simmer 10 minutes. It should be thick like porridge.","Ewedu: wash the leaves and strip them off the stems. Boil in water with the baking soda for 8 minutes until soft.","Mash or blend the leaves until smooth and slimy. Return to low heat, add iru and salt, cook 3 minutes.","Serve gbegiri and ewedu together with stew and amala."],
  tip:"In Kenya, ewedu leaves are sold as mrenda (jute mallow). Same plant." },
{ id:"melon-soup", country:"Nigerian", name:"Melon Soup (Egusi)", aka:["melon soup","egusi","egusi soup"], cat:"soup", level:3, type:"meal", time:"60 min", serves:4,
  ing:["1.5 cups ground egusi (melon seeds)","1/2 cup palm oil","1 onion, chopped","2 scotch bonnet peppers","500 g beef or assorted meat","1 piece dried fish","2 cups spinach or pumpkin leaves, chopped","2 tbsp ground crayfish (optional)","2 cups meat stock","Salt and stock cubes"],
  steps:["Boil the beef with onion, salt and stock cubes until tender. Keep the stock.","Mix the ground egusi with a little chopped onion and 3 to 4 tbsp water to make a thick paste.","Heat the palm oil. Fry the remaining onion 2 minutes.","Spoon the egusi paste into the oil in small lumps. Do not stir for 5 minutes, let it set.","Gently stir. Pour in the stock, add blended pepper, crayfish and seasoning. Simmer 15 minutes.","Add the meat, dried fish and leaves. Cook 5 more minutes and serve with swallow."],
  tip:"No egusi? Ground pumpkin seeds work. Do not stir at first or the egusi will not form lumps." },
{ id:"obolo-soup", country:"Nigerian", name:"Obolo Soup (Ogbono)", aka:["obolo soup","obolo","ogbono","ogbono soup","obono soup"], cat:"soup", level:2, type:"meal", time:"40 min", serves:4,
  ing:["1/2 cup ground ogbono","1/2 cup palm oil","500 g beef or assorted meat","1 piece stockfish or dried fish","1 onion","2 scotch bonnet peppers","2 tbsp ground crayfish","2 cups stock","1 cup spinach or ugu leaves","Salt and stock cubes"],
  steps:["Boil the meat and fish with onion, salt and stock cubes until tender. Keep the stock.","Heat the palm oil on LOW heat in a clean pot.","Add the ground ogbono and stir until it melts into the oil like a paste.","Add the stock a little at a time, stirring, until the soup draws and thickens.","Add blended pepper, crayfish, meat and fish. Cover and simmer 10 minutes, stirring now and then.","Add the leaves, cook 3 minutes and serve with swallow."],
  tip:"Keep the heat low when melting ogbono. High heat makes it burn and refuse to draw." },
{ id:"vegetable-soup", country:"Nigerian", name:"Vegetable Soup (Efo Riro)", aka:["vegetable soup","efo riro","efo","spinach soup"], cat:"soup", level:2, type:"meal", time:"40 min", serves:4,
  ing:["2 bunches spinach (or sukuma), washed and chopped","4 tomatoes","2 red bell peppers","2 scotch bonnet peppers","1 onion","1/2 cup palm oil","500 g assorted meat or fish","1 tbsp locust beans (iru)","2 tbsp ground crayfish","Salt and stock cubes"],
  steps:["Blend the tomatoes, bell peppers and scotch bonnet. Boil down until thick, about 10 minutes.","Heat the palm oil. Fry the chopped onion 2 minutes.","Add the pepper mix and iru. Fry 10 minutes until the oil floats.","Add the cooked meat or fish, crayfish, salt and stock cubes. Simmer 5 minutes.","Add the chopped vegetables. Stir, cover and cook only 3 to 5 minutes.","Serve with swallow or white rice."],
  tip:"Add the vegetables last. They only need minutes. Overcooked greens go dull and watery." },
{ id:"banga-soup", country:"Nigerian", name:"Banga Soup", aka:["banga soup","banga","palm nut soup"], cat:"soup", level:3, type:"meal", time:"80 min", serves:4,
  ing:["2 cans palm nut cream (or 1 kg fresh palm nuts)","500 g beef or assorted meat","2 pieces dried fish","1 onion","2 scotch bonnet peppers","2 tbsp ground crayfish","2 tbsp banga spice mix","A handful of scent leaves or basil","Salt and stock cubes"],
  steps:["Boil the meat and dried fish with onion, salt and stock cubes until tender. Keep the stock.","Fresh nuts only: boil the palm nuts 30 minutes, pound lightly, then squeeze out the juice with hot water and strain. Canned cream skips this step.","Pour the palm nut juice or cream into a pot. Boil 20 to 25 minutes until it thickens and the oil rises.","Add the meat, fish, stock, banga spice, crayfish and blended pepper.","Simmer 15 minutes. Taste and adjust salt.","Add the scent leaves, cook 2 minutes. Serve with starch swallow or white rice."],
  tip:"Canned palm nut cream saves over an hour and works well. Boil it long enough to lose the raw taste." },
{ id:"pepper-soup", country:"Nigerian", name:"Pepper Soup", aka:["pepper soup","goat pepper soup","fish pepper soup","chicken pepper soup"], cat:"soup", level:2, type:"meal", time:"50 min", serves:4,
  ing:["1 kg goat meat, chicken or fish","2 tbsp pepper soup spice","2 scotch bonnet peppers, blended","1 onion, sliced","1 tbsp grated ginger","3 garlic cloves","A handful of scent leaves or basil","Salt and stock cubes","4 cups water"],
  steps:["Wash the meat. Season with onion, garlic, salt and stock cubes.","Boil in the water for 20 to 30 minutes until nearly tender (chicken 15 minutes).","Add the pepper soup spice, ginger and blended scotch bonnet.","Simmer 15 minutes. Fish only needs 8 to 10 minutes total.","Add the scent leaves in the last 2 minutes. Taste and adjust.","Serve hot in bowls."],
  tip:"Pepper soup is meant to be thin and fiery. Do not thicken it." },
{ id:"bitter-leaf-soup", country:"Nigerian", name:"Bitter Leaf Soup", aka:["bitter leaf soup","bitterleaf soup","ofe onugbu","onugbu"], cat:"soup", level:3, type:"meal", time:"85 min", serves:4,
  ing:["2 handfuls bitter leaf, washed","500 g beef or assorted meat","1 piece stockfish or dried fish","4 small cocoyam (or nduma/arrowroot)","1/3 cup palm oil","2 tbsp ground crayfish","2 scotch bonnet peppers","1 onion","Salt and stock cubes"],
  steps:["Boil the meat and fish with onion, salt and stock cubes until tender.","Boil the cocoyam until very soft. Peel and pound or blend into a smooth paste.","Add lumps of the paste to the pot of stock. Cook 15 minutes, stirring until it dissolves and thickens the soup.","Add palm oil, crayfish, blended pepper and seasoning. Simmer 10 minutes.","Wash the bitter leaf by squeezing it in several changes of water until the foam and most bitterness are gone.","Add the leaves, cook 10 minutes and serve with swallow."],
  tip:"Wash the leaves well. How much bitterness stays is your choice, a little is the point of the soup." },
// ---------- SAUCES ----------
{ id:"stew-sauce", country:"Nigerian", name:"Stew Sauce", aka:["stew sauce","nigerian stew","red stew","tomato stew","pepper stew"], cat:"sauce", level:2, type:"meal", time:"55 min", serves:5,
  ing:["6 large tomatoes","3 red bell peppers","2 scotch bonnet peppers","2 onions","1 cup vegetable oil","2 tbsp tomato paste","1 cup meat or chicken stock","1 tsp thyme","1 tsp curry powder","Salt and stock cubes"],
  steps:["Blend the tomatoes, bell peppers, scotch bonnet and 1 onion. Boil in a pot for 15 to 20 minutes until the water has dried and it is thick.","In another pot, heat the oil and fry the sliced onion until soft.","Add the tomato paste and fry 3 minutes.","Add the thick pepper mix. Fry 20 to 25 minutes, stirring, until the oil rises to the top and the raw smell is gone.","Add stock, thyme, curry, salt and stock cubes. Simmer 5 to 10 minutes.","Add your cooked meat or fish, or serve over rice and swallow."],
  tip:"Boiling the water off first prevents sour stew. A dark red color with oil on top means it is ready." },
{ id:"peppered-ponmo-sauce", country:"Nigerian", name:"Peppered Ponmo Sauce", aka:["peppered ponmo","ponmo sauce","peppered cow skin","ponmo sauce"], cat:"sauce", level:2, type:"snack", time:"60 min", serves:4,
  ing:["500 g ponmo (cow skin)","3 red bell peppers","3 scotch bonnet peppers","2 onions","1/3 cup oil","1 tbsp grated ginger","2 garlic cloves","Salt and stock cubes"],
  steps:["Wash the ponmo well. Boil with salt, onion and a stock cube for 30 to 40 minutes until soft but not falling apart.","Cut into bite-size pieces.","Blend the peppers coarsely. Cook them in a pot for 8 minutes to remove the water.","Heat the oil and fry the sliced onion, ginger and garlic for 2 minutes.","Add the cooked pepper. Fry 10 minutes.","Add the ponmo, salt and stock cube. Simmer 10 minutes until the sauce clings to the pieces."],
  tip:"Ponmo drinks up flavor. Boil it with seasoning first so it is not bland inside." },
{ id:"chicken-curry-sauce", country:"Nigerian", name:"Chicken Curry Sauce", aka:["chicken curry sauce","chicken curry","curry sauce"], cat:"sauce", level:2, type:"meal", time:"45 min", serves:4,
  ing:["1 kg chicken pieces","3 tbsp curry powder","1 tsp thyme","2 onions, sliced","1 green bell pepper, sliced","1 carrot, sliced (optional)","3 garlic cloves","1 tbsp grated ginger","1/3 cup oil","1 tbsp flour or cornflour in 3 tbsp cold water","Salt and stock cubes"],
  steps:["Season the chicken with 1 tbsp curry, garlic, ginger, salt and stock cubes. Boil 20 minutes in a little water. Keep the stock.","Heat the oil and fry the chicken pieces lightly until golden. Remove.","In the same oil, fry the onions 3 minutes. Add the rest of the curry and thyme and stir 1 minute.","Pour in 1.5 cups of the chicken stock. Add the chicken back.","Simmer 10 minutes. Stir in the flour mix to thicken.","Add the bell pepper and carrot, cook 3 minutes. Serve with rice."],
  tip:"Fry the curry powder in the oil for a minute. It removes the raw powdery taste." },
{ id:"egg-sauce", country:"Nigerian", name:"Egg Sauce", aka:["egg sauce","nigerian egg sauce","scrambled egg sauce"], cat:"sauce", level:1, type:"meal", time:"20 min", serves:3,
  ing:["5 eggs","3 tomatoes, chopped","1 onion, chopped","1 red bell pepper, chopped","1 scotch bonnet, chopped","1/3 cup oil","1/2 tsp thyme","Salt and stock cube"],
  steps:["Heat the oil and fry the onion for 2 minutes.","Add the tomatoes, bell pepper and scotch bonnet. Cook 8 to 10 minutes until thick and the oil shows on top.","Add thyme, salt and stock cube.","Beat the eggs and pour them in. Lower the heat.","Stir gently until the eggs are just set, about 2 minutes.","Serve with white rice, boiled yam, bread or plantain."],
  tip:"Cook the tomato sauce properly first. Eggs only need a couple of minutes at the end." },
{ id:"locust-beans-sauce", country:"Nigerian", name:"Locust Beans Sauce", aka:["locust beans sauce","locust bean sauce","iru sauce","iru","dawadawa sauce"], cat:"sauce", level:2, type:"meal", time:"35 min", serves:4,
  ing:["3 tbsp locust beans (iru)","4 tomatoes","2 red bell peppers","2 scotch bonnet peppers","2 onions","1/2 cup oil","2 tbsp ground crayfish","Salt and stock cubes"],
  steps:["Wash the iru in warm water and pound it lightly to break up the lumps.","Blend the tomatoes, bell peppers and scotch bonnet. Boil down until thick, about 10 minutes.","Heat the oil and fry the sliced onions until golden.","Add the pepper mix. Fry 10 minutes until the oil rises.","Add the iru, crayfish, salt and stock cubes. Simmer 8 minutes.","Serve with yam, rice or swallow."],
  tip:"Iru is strong. Start with 2 tbsp and add more if you want a deeper smell and taste." },
// ---------- TOPPINGS ----------
{ id:"fried-beef", country:"Nigerian", name:"Fried Beef", aka:["fried beef","beef topping","boiled beef"], cat:"topping", level:1, type:"meal", time:"50 min", serves:4,
  ing:["1 kg beef, cut in chunks","1 onion","3 garlic cloves","1 tbsp grated ginger","1 tsp thyme","1 tsp curry powder","Stock cubes and salt","Oil for frying"],
  steps:["Wash the beef. Add onion, garlic, ginger, thyme, curry, salt and stock cubes.","Cook with only a little water, covered, for 30 to 40 minutes until tender.","Boil off any remaining liquid. Save the stock for stews and soups.","Heat oil and fry the beef on medium-high heat for 5 to 8 minutes until browned.","Drain on paper and serve on rice or with soup."],
  tip:"Do not throw away the beef stock. It makes stew, jollof and soup taste much better." },
{ id:"fried-chicken", country:"Nigerian", name:"Fried Chicken", aka:["fried chicken","chicken topping","nigerian fried chicken"], cat:"topping", level:2, type:"meal", time:"55 min", serves:4,
  ing:["1 whole chicken, cut up","1 onion","3 garlic cloves","1 tbsp grated ginger","1 tsp thyme","1 tsp curry powder","1 tsp paprika","Stock cubes and salt","Oil for frying"],
  steps:["Season the chicken with all the spices, onion, garlic and ginger. Rest 30 minutes.","Add a splash of water and cook covered on medium heat for 15 to 20 minutes until almost done.","Drain and pat the pieces dry.","Heat oil on medium heat. Fry 8 to 10 minutes, turning, until deep golden and crisp.","Drain and serve."],
  tip:"Cooking it first then frying means the inside is done while the skin stays crisp, not burnt." },
{ id:"fried-turkey", country:"Nigerian", name:"Fried Turkey", aka:["fried turkey","turkey wings","turkey topping"], cat:"topping", level:2, type:"meal", time:"80 min", serves:4,
  ing:["1 kg turkey wings or drumsticks","1 onion","4 garlic cloves","1 tbsp grated ginger","1 tsp thyme","1 tsp curry powder","Stock cubes and salt","Oil for frying"],
  steps:["Wash the turkey. Season with all the spices, onion, garlic and ginger. Rest 30 minutes.","Add a little water and cook covered 40 to 50 minutes until the meat is tender. Turkey is tougher than chicken.","Let the liquid dry out. Pat the meat dry.","Fry in hot oil for 5 to 7 minutes, turning, until golden.","Serve with rice, jollof or sauce."],
  tip:"Give turkey more boiling time than chicken. It will not soften once fried." },
{ id:"fried-titus-fish", country:"Nigerian", name:"Fried Titus Fish", aka:["titus fish","titus","fried titus","mackerel"], cat:"topping", level:1, type:"meal", time:"30 min", serves:3,
  ing:["3 titus fish (mackerel), cleaned","1 tsp thyme","1 tsp curry powder","2 garlic cloves, grated","1 tsp grated ginger","1 stock cube, crushed","Salt","Oil for frying"],
  steps:["Thaw the fish fully. Wash and rub with salt and lemon or lime. Rinse.","Make 2 or 3 cuts across each side.","Rub with thyme, curry, garlic, ginger, stock cube and salt. Rest 20 minutes.","Pat completely dry.","Fry in hot oil on medium heat, 6 to 7 minutes each side, until golden and crisp.","Drain and serve with stew and rice."],
  tip:"Dry the fish well before frying to avoid oil splatter and soggy skin." },
{ id:"shawa-fish", country:"Nigerian", name:"Shawa Fish (Smoked)", aka:["shawa fish","sharwa fish","sharwa","shawa","smoked fish"], cat:"topping", level:1, type:"meal", time:"25 min", serves:3,
  ing:["2 pieces smoked shawa fish","Warm water for soaking","Oil for frying (optional)","1 onion, sliced","Pepper, stock cube and salt"],
  steps:["Soak the fish in warm water for 10 to 15 minutes to soften and remove dirt.","Wash gently and remove bones where you can.","Break into big chunks.","Add straight into soups or stew and simmer 10 minutes. Or lightly fry with onion for 3 minutes."],
  tip:"Smoked fish is already salty, so taste before adding salt to the dish." },
{ id:"red-fish", country:"Nigerian", name:"Red Fish (Fried)", aka:["red fish","fried red fish","red snapper","snapper"], cat:"topping", level:2, type:"meal", time:"35 min", serves:3,
  ing:["1 whole red fish (snapper), cleaned and scaled","1 onion","3 garlic cloves","1 tsp ginger","1 tsp thyme","1 tsp curry powder","1 stock cube","Salt and pepper","Oil for frying"],
  steps:["Wash the fish with salt and lemon. Rinse.","Score the sides 2 or 3 times.","Blend or grate the onion, garlic and ginger. Rub on the fish with the spices and stock cube.","Rest 20 to 30 minutes.","Pat dry. Fry in hot oil on medium heat for 7 to 8 minutes each side until golden.","Serve whole with stew or sauce."],
  tip:"Do not flip too early. Wait until it releases from the pan on its own." },
{ id:"panla-fish", country:"Nigerian", name:"Panla Fish", aka:["panla fish","panla","fried panla"], cat:"topping", level:1, type:"meal", time:"30 min", serves:3,
  ing:["3 to 4 panla fish pieces","Hot water and lime for washing","1 onion","1 tsp thyme","1 stock cube","Salt","Oil for frying"],
  steps:["Pour hot water over the fish and rinse it well. Rub with lime.","Season with onion, thyme, stock cube and a little salt.","For soups and stews: add the pieces straight to the pot and simmer 10 to 15 minutes.","To fry: pat dry and fry in hot oil 5 minutes each side until golden."],
  tip:"Rinse with hot water first to remove the strong smell." },
{ id:"kote-fish", country:"Nigerian", name:"Kote Fish", aka:["kote fish","kote","fried kote"], cat:"topping", level:1, type:"meal", time:"30 min", serves:3,
  ing:["3 kote fish, cleaned","1 tsp thyme","1 tsp curry powder","2 garlic cloves","1 stock cube","Salt","Oil for frying"],
  steps:["Wash the fish with salt and lime. Rinse.","Season with thyme, curry, grated garlic, stock cube and salt. Rest 20 minutes.","Pat dry.","Fry in medium-hot oil 5 to 6 minutes each side until crisp.","Serve with sauce or soup."],
  tip:"Medium heat keeps the fish juicy inside while the outside crisps." },
{ id:"boiled-eggs", country:"Nigerian", name:"Boiled Eggs", aka:["boiled eggs","boiled egg","egg topping","hard boiled eggs"], cat:"topping", level:1, type:"snack", time:"15 min", serves:4,
  ing:["4 to 6 eggs","Water","Pinch of salt","Cold water or ice"],
  steps:["Lower the eggs gently into boiling water with a pinch of salt.","Boil 10 minutes for hard eggs, 7 for soft centers.","Move to cold water for 5 minutes.","Crack all over and peel.","Halve or slice on top of rice, sauce or stew."],
  tip:"Cold water after boiling stops the grey ring and makes peeling easier." },
{ id:"ponmo", country:"Nigerian", name:"Ponmo (Cow Skin)", aka:["ponmo","cow skin","cowskin","kpomo"], cat:"topping", level:2, type:"meal", time:"70 min", serves:4,
  ing:["500 g ponmo (cow skin)","1 onion","1 tsp thyme","Stock cubes and salt","Water","Optional: oil for frying"],
  steps:["Wash the ponmo well and cut into pieces.","Boil with onion, thyme, salt and stock cubes for 40 to 60 minutes until soft with a slight chew.","Drain, keep the stock for soup.","Serve in soups and stew, or fry the pieces in hot oil 4 minutes until browned."],
  tip:"A pressure cooker cuts the time to 20 minutes." },
{ id:"fried-pork", country:"Nigerian", name:"Fried Pork", aka:["fried pork","pork topping","pork"], cat:"topping", level:2, type:"meal", time:"70 min", serves:4,
  ing:["1 kg pork belly or ribs, in chunks","1 onion","4 garlic cloves","1 tbsp grated ginger","1 tsp thyme","1 tsp paprika","Stock cubes and salt","Oil for frying"],
  steps:["Season the pork with all the spices, onion, garlic and ginger. Rest 30 minutes.","Add a little water and cook covered 30 to 40 minutes until tender.","Let the water dry out. Pat the meat dry.","Fry in hot oil, turning, for 6 to 8 minutes until the edges are crisp and golden.","Serve with rice, sauce or kachumbari."],
  tip:"Pork cooks fast but needs to be fully cooked through. Cut a piece open to check." },
// ---------- SWALLOW ----------
{ id:"semo", country:"Nigerian", name:"Semo", aka:["semo","semolina","semovita"], cat:"swallow", level:1, type:"meal", time:"15 min", serves:2,
  ing:["2 cups semolina","3 cups water","1/2 cup cold water"],
  steps:["Boil 3 cups of water.","Mix 1/2 cup semo with the cold water to a smooth paste. Stir into the boiling water and simmer 2 minutes.","Sprinkle in the rest of the semo bit by bit, stirring hard so no lumps form.","Cover on low heat 3 minutes.","Stir and press until smooth and stretchy. Mould in a wet bowl and serve with soup."],
  tip:"Add the semo slowly. Dumping it in all at once makes lumps." },
{ id:"fufu", country:"Nigerian", name:"Fufu", aka:["fufu","cassava fufu","akpu"], cat:"swallow", level:2, type:"meal", time:"20 min", serves:2,
  ing:["2 cups fufu flour (cassava flour)","3 cups water","1 cup cold water"],
  steps:["Mix 1 cup of flour with the cold water until smooth.","Pour into 2 cups of boiling water, stirring non-stop, until it thickens into a sticky paste.","Lower the heat. Add the remaining flour in small amounts, turning and pressing with a wooden spoon.","Cover 2 to 3 minutes. Stir again until smooth and stretchy.","Mould in a wet bowl and serve with soup."],
  tip:"In Kenya, unga wa muhogo (cassava flour) works for fufu." },
{ id:"amala", country:"Nigerian", name:"Amala", aka:["amala","yam flour swallow","elubo","black amala"], cat:"swallow", level:2, type:"meal", time:"20 min", serves:2,
  ing:["2 cups yam flour (elubo)","3 cups water"],
  steps:["Boil the water.","Lower the heat. Sprinkle in the flour bit by bit with one hand while stirring hard with the other.","Cover 5 minutes on low heat.","Stir and press with a wooden spoon, turning for 3 to 5 minutes until smooth and dark.","Mould and serve with ewedu, gbegiri or soup."],
  tip:"Keep stirring hard at the start. If lumps form, press them against the side of the pot." },
{ id:"eba", country:"Nigerian", name:"Eba", aka:["eba","garri","gari","eba and garri"], cat:"swallow", level:1, type:"meal", time:"5 min", serves:1,
  ing:["1 cup garri","1 cup boiling water (about)"],
  steps:["Pour the boiling water into a bowl.","Sprinkle in the garri and let it sit for 1 minute.","Stir vigorously with a wooden spoon until smooth and stretchy.","Add more garri if it is too soft. Serve right away with soup."],
  tip:"The water must be boiling hot. Lukewarm water gives hard lumps." },
{ id:"starch-swallow", country:"Nigerian", name:"Starch Swallow", aka:["starch","starch swallow","usi","edo starch"], cat:"swallow", level:2, type:"meal", time:"10 min", serves:2,
  ing:["1 cup cassava starch","1 cup cold water","2 cups boiling water"],
  steps:["Mix the starch with the cold water in a bowl until smooth.","Pour the boiling water in slowly while stirring fast.","Keep stirring until the mixture turns clear, thick and jelly-like.","Mould with a wet spoon and serve with banga soup or other soup."],
  tip:"Pour the boiling water immediately after mixing or the starch settles at the bottom." },
{ id:"pounded-yam", country:"Nigerian", name:"Pounded Yam", aka:["pounded yam","poundo","iyan","poundo yam"], cat:"swallow", level:3, type:"meal", time:"50 min", serves:3,
  ing:["1 kg white yam, peeled and cubed","Water for boiling","Pinch of salt","Alternative: 2 cups poundo yam flour and 3 cups water"],
  steps:["Boil the yam in water with a pinch of salt for 20 to 25 minutes until very soft.","Drain, keeping a little of the water.","Pound in a mortar while hot until smooth and stretchy. A food processor works too, add small splashes of the water.","Mould in a wet bowl and serve with soup.","Flour method: stir the poundo into boiling water like ugali, cover 3 minutes and stir until smooth."],
  tip:"Pound while the yam is hot. It gets hard and lumpy as it cools." },
// ---------- OTHER DELICACIES ----------
{ id:"fish-barbecue", country:"Nigerian", name:"Fish Barbecue", aka:["fish barbecue","barbecue fish","grilled fish","bbq fish"], cat:"other", level:2, type:"meal", time:"90 min", serves:3,
  ing:["2 whole tilapia or catfish, cleaned","1 onion","4 garlic cloves","1 tbsp ginger","1 scotch bonnet","1 tbsp suya spice or paprika","1 tsp thyme","1 stock cube","1/4 cup oil","Salt, lemon"],
  steps:["Wash the fish with salt and lemon. Score the sides.","Blend the onion, garlic, ginger and scotch bonnet. Mix with spices, stock cube, salt and oil.","Rub the marinade inside and out. Marinate 1 hour.","Grill on medium charcoal 10 to 12 minutes per side, brushing with oil. Oven option: 220 C for 25 minutes.","Serve with kachumbari, plantain or chips."],
  tip:"Oil the grill and wait until the skin releases before turning, or it tears." },
{ id:"chicken-barbecue", country:"Nigerian", name:"Chicken Barbecue", aka:["chicken barbecue","barbecue chicken","bbq chicken","grilled chicken"], cat:"other", level:2, type:"meal", time:"100 min", serves:4,
  ing:["1 kg chicken drumsticks or thighs","1 onion","4 garlic cloves","1 tbsp ginger","1 tsp thyme","1 tsp paprika","1 tsp curry powder","Stock cubes and salt","3 tbsp BBQ sauce or tomato sauce mixed with 1 tbsp honey","2 tbsp oil"],
  steps:["Season the chicken with the blended onion, garlic, ginger, spices, salt, stock cubes and oil. Marinate at least 1 hour.","Cook covered with a splash of water for 15 minutes to part-cook it.","Grill over medium charcoal for 10 minutes, turning.","Brush with the BBQ sauce and grill 5 to 8 minutes more, turning, until charred in places and cooked through.","Rest 5 minutes and serve."],
  tip:"Add the sauce late. Sugar in it burns fast over the fire." },
{ id:"suya", country:"Nigerian", name:"Suya", aka:["suya","beef suya","nigerian suya"], cat:"other", level:2, type:"snack", time:"90 min", serves:4,
  ing:["500 g beef sirloin, sliced very thin","1/2 cup roasted ground peanuts","2 tbsp paprika","1 tbsp cayenne or chili powder","1 tsp ground ginger","1 tsp garlic powder","1 tsp onion powder","1 stock cube, crushed","1 tsp salt","3 tbsp oil","To serve: sliced onion, tomato and cabbage"],
  steps:["Mix the peanuts, paprika, cayenne, ginger, garlic powder, onion powder, stock cube and salt. This is the yaji spice.","Coat the beef slices in oil, then in half the yaji. Marinate 1 to 2 hours.","Thread onto skewers.","Grill over hot charcoal 4 to 6 minutes each side, brushing with a little oil, until browned and slightly charred.","Sprinkle the remaining yaji on top. Serve with onion, tomato and cabbage."],
  tip:"Slice the meat thin and across the grain so it stays tender over high heat." },
{ id:"abacha", country:"Nigerian", name:"Abacha", aka:["abacha","african salad","abacha and ugba"], cat:"other", level:2, type:"snack", time:"45 min", serves:4,
  ing:["2 cups dry shredded cassava (abacha)","1/2 cup palm oil","1 tsp edible potash (akanwu), dissolved in 2 tbsp warm water","1 cup ugba (oil bean slices)","2 tbsp ground crayfish","1 small onion, sliced","1 scotch bonnet, ground","A handful of utazi leaves, sliced thin","2 garden eggs, sliced","Fried fish or ponmo","Salt and stock cube"],
  steps:["Soak the abacha in cold water 30 minutes. Boil 5 minutes until just soft, drain and rinse in cold water. Drain well.","Stir the palm oil with the potash water until it turns thick and creamy yellow.","Mix in the scotch bonnet, crayfish, stock cube and salt.","Fold in the abacha and ugba until evenly coated.","Top with onion, utazi leaves, garden egg and fish or ponmo. Serve at room temperature."],
  tip:"Mix the palm oil and potash until it is thick like cream. That is what makes it cling to the abacha." },
{ id:"coleslaw", country:"Nigerian", name:"Coleslaw", aka:["coleslaw","cole slaw","slaw","salad cream salad"], cat:"other", level:1, type:"snack", time:"15 min", serves:4,
  ing:["1/2 small cabbage, shredded fine","2 carrots, grated","1/2 onion, sliced thin","1/2 cup sweet corn (optional)","1/2 cup mayonnaise or salad cream","1 tbsp lemon juice or vinegar","1 tsp sugar","Salt and black pepper"],
  steps:["Shred the cabbage and grate the carrots. Add onion and sweet corn.","Mix mayonnaise, lemon juice, sugar, salt and pepper.","Pour over the vegetables and toss.","Chill 10 minutes and serve."],
  tip:"Sprinkle a little salt on the cabbage first, rest 5 minutes and squeeze out water. The slaw stays crunchy." },
{ id:"stir-fried-noodles", country:"Nigerian", name:"Stir Fried Noodles", aka:["stir fried noodles","stir fry noodles","fried noodles","stir-fried noodles"], cat:"other", level:1, type:"meal", time:"20 min", serves:3,
  ing:["2 packs noodles","1 carrot, cut thin","1/2 cup green beans, sliced","1 red bell pepper, sliced","2 spring onions","2 garlic cloves","2 eggs or 200 g chicken/shrimps","3 tbsp oil","2 tbsp soy sauce","The noodle seasoning sachets","Pepper"],
  steps:["Boil the noodles 2 minutes. Drain and rinse with cold water.","Heat the oil on high. Scramble the eggs, or cook the chicken or shrimps through. Set aside.","In the same pan, stir-fry the garlic and carrot 1 minute. Add the green beans and bell pepper, 2 more minutes.","Add the noodles, soy sauce and seasoning. Toss on high heat for 2 minutes.","Add the eggs or meat and spring onions. Toss and serve."],
  tip:"Keep the heat high and the pan moving, or the noodles turn soft and sticky." },
{ id:"stir-fried-spaghetti", country:"Nigerian", name:"Stir Fried Spaghetti", aka:["stir fried spaghetti","stir fry spaghetti","fried spaghetti","spaghetti","stir-fried spaghetti"], cat:"other", level:1, type:"meal", time:"25 min", serves:3,
  ing:["300 g spaghetti","1 onion, sliced","1 carrot, sliced thin","1 green bell pepper, sliced","1/2 cup green peas","2 sausages or 150 g chicken, cut small","1/4 cup oil","1 tsp curry powder","1 tsp thyme","1 stock cube","Salt and pepper"],
  steps:["Boil the spaghetti in salted water until al dente, about 8 minutes. Drain and toss with a little oil.","Heat the oil and fry the sausages or chicken until cooked. Remove and set aside.","Fry the onion 2 minutes. Add the carrot and peas, then the bell pepper.","Add curry, thyme, stock cube, salt and pepper.","Add the spaghetti and the meat. Toss on high heat for 3 minutes.","Serve hot."],
  tip:"Cook the spaghetti slightly firm. It finishes cooking when you stir-fry it." },
// ---------- GHANA ----------
{ id:"ghana-jollof", country:"Ghanaian", name:"Ghana Jollof", aka:["ghana jollof","ghanaian jollof","ghana jollof rice"], cat:"rice", level:3, type:"meal", time:"75 min", serves:4,
  ing:["3 cups basmati or long-grain rice","4 tomatoes","2 onions","3 tbsp tomato paste","1 scotch bonnet","1 tbsp grated ginger","4 garlic cloves","1/2 cup oil","2 cups chicken or beef stock","1 tsp curry powder","1 tsp thyme","2 bay leaves","Salt and stock cubes","Optional: diced carrots and green beans"],
  steps:["Blend the tomatoes, 1 onion, scotch bonnet, ginger and garlic.","Fry the sliced onion in the oil until golden. Add the tomato paste and fry 3 minutes.","Add the blended mix. Cook 15 to 20 minutes, stirring, until thick and the oil floats on top.","Add stock, curry, thyme, bay leaves, salt and stock cubes. Bring to a boil.","Add the washed rice (and vegetables if using). Stir once. Liquid should only just cover the rice.","Cover tightly with foil and a lid. Cook on the lowest heat 30 minutes without stirring.","Fluff gently and serve with fried chicken, fried plantain and shito."],
  tip:"Ghana jollof is usually made with fragrant rice, ginger and garlic. Washing the rice well keeps it from going sticky." },
{ id:"waakye", country:"Ghanaian", name:"Waakye", aka:["waakye","waakye rice","rice and beans ghana"], cat:"rice", level:2, type:"meal", time:"90 min", serves:4,
  ing:["2 cups rice","1 cup black-eyed beans (soaked overnight)","A bunch of dried waakye leaves (millet leaf sheaths)","1 tsp salt","Water","To serve: shito, boiled eggs, gari, fried plantain, spaghetti"],
  steps:["Rinse the soaked beans and put in a pot with the waakye leaves and plenty of water.","Boil 30 to 40 minutes until the beans are nearly soft. The water turns deep red-brown.","Remove the leaves. Add the washed rice and salt. Add water to cover by about 2 cm.","Cook on medium heat until the water reduces, then cover and cook on low for 15 minutes until the rice is done.","Serve hot with shito, boiled eggs and fried plantain."],
  tip:"The leaves give the color. Without them the waakye still tastes good but will be paler." },
{ id:"banku", country:"Ghanaian", name:"Banku", aka:["banku","banku and tilapia","banku and okro stew"], cat:"swallow", level:3, type:"meal", time:"45 min", serves:3,
  ing:["2 cups fermented corn dough","1 cup cassava dough (or 1/2 cup cassava flour)","3 cups water","1/2 tsp salt","To serve: grilled tilapia, hot pepper sauce or okro stew"],
  steps:["Mix the corn dough, cassava dough and salt with 2 cups of water until smooth with no lumps.","Cook on medium heat, stirring constantly with a strong wooden spoon, for about 10 minutes until it thickens.","Add the last cup of water gradually. Keep turning and beating against the pot for 15 to 20 minutes.","Cover on low heat for 5 minutes.","Beat once more until smooth and stretchy. Mould in a wet bowl and serve with grilled tilapia and pepper sauce."],
  tip:"Banku needs hard beating. The smoother and more stretchy you make it, the better it eats." },
{ id:"red-red", country:"Ghanaian", name:"Red Red", aka:["red red","red-red","beans and plantain ghana"], level:2, type:"meal", time:"70 min", serves:4,
  ing:["2 cups black-eyed beans, soaked","1/2 cup palm oil","1 onion, chopped","2 tomatoes, chopped","1 tbsp grated ginger","1 scotch bonnet","2 ripe plantains","Oil for frying","Salt","Optional: gari and fried fish"],
  steps:["Boil the beans in plenty of water for 40 minutes until soft.","In another pot, heat the palm oil. Fry the onion until soft.","Add the tomatoes, ginger and scotch bonnet. Cook 8 minutes.","Add the drained beans and a little of the cooking water. Salt and simmer 15 minutes.","Slice the plantains and fry in hot oil until deep golden.","Serve the beans with the fried plantain, and gari or fish on the side."],
  tip:"The palm oil gives it the red color and the name. Use ripe, spotty plantains for the sweet contrast." },
{ id:"kelewele", country:"Ghanaian", name:"Kelewele", aka:["kelewele","spicy fried plantain","ghana fried plantain"], level:1, type:"snack", time:"20 min", serves:3,
  ing:["3 ripe plantains","1 tsp grated ginger","1/2 tsp cayenne pepper","1/4 tsp ground cloves","1/2 tsp salt","1/2 small onion, grated","Oil for frying","Optional: roasted peanuts"],
  steps:["Peel the plantains and cut into cubes.","Toss with ginger, cayenne, cloves, salt and onion. Rest 10 minutes.","Heat oil on medium-high heat.","Fry in batches for 3 to 4 minutes until dark golden and crisp at the edges.","Drain and serve hot with roasted peanuts."],
  tip:"Use plantains that are yellow with black spots. Green ones will not caramelize." },
{ id:"ghana-light-soup", country:"Ghanaian", name:"Light Soup", aka:["light soup","ghana light soup","goat light soup"], cat:"soup", level:2, type:"meal", time:"70 min", serves:4,
  ing:["1 kg goat meat or chicken","4 tomatoes","1 onion","2 scotch bonnet peppers","1 tbsp grated ginger","3 garlic cloves","2 garden eggs (small eggplants)","1 tsp dried basil","Salt and stock cubes","5 cups water"],
  steps:["Season the meat with onion, garlic, ginger, salt and stock cubes. Boil in the water 25 to 30 minutes.","Blend the tomatoes, scotch bonnet and a little more ginger. Add to the pot.","Add the whole garden eggs and basil.","Simmer 25 minutes until the meat is tender and the soup has a clear red broth.","Mash the garden eggs into the soup, taste and adjust salt.","Serve with fufu, banku or rice."],
  tip:"It should be a thin, clear, peppery soup, not thick like a stew." },
{ id:"groundnut-soup", country:"Ghanaian", name:"Groundnut Soup", aka:["groundnut soup","peanut soup","nkate nkwan"], cat:"soup", level:3, type:"meal", time:"80 min", serves:4,
  ing:["1 cup unsweetened peanut butter","1 kg chicken or goat meat","3 tomatoes","1 onion","1 tbsp grated ginger","2 scotch bonnet peppers","1 tbsp tomato paste","Salt and stock cubes","5 cups water"],
  steps:["Season the meat with half the onion, ginger, salt and stock cubes. Boil 20 to 25 minutes in 4 cups of water.","Blend the tomatoes, remaining onion and scotch bonnet. Add to the pot with the tomato paste.","Dissolve the peanut butter in 1 cup of warm stock or water until smooth.","Pour it into the pot, stirring.","Simmer on low heat 30 to 40 minutes, stirring now and then, until the oil rises to the top.","Serve with fufu, omo tuo (rice balls) or rice."],
  tip:"Use plain unsweetened peanut butter. Sweetened butter ruins the soup." },
{ id:"shito", country:"Ghanaian", name:"Shito (Black Pepper Sauce)", aka:["shito","black pepper sauce","ghana pepper sauce","shitor"], cat:"sauce", level:3, type:"snack", time:"75 min", serves:10,
  ing:["2 cups vegetable oil","1 cup finely chopped onion","2 tbsp grated ginger","6 garlic cloves, minced","1/2 cup ground dried shrimp or dried fish","1/2 cup dried hot pepper powder","3 tbsp tomato paste","1 tsp salt","1 stock cube"],
  steps:["Heat the oil in a pot on medium heat. Fry the onion until deep golden brown, about 15 minutes.","Add ginger and garlic. Fry 3 minutes.","Add the tomato paste and fry 5 minutes.","Add the ground dried shrimp, pepper powder, salt and stock cube. Lower the heat.","Simmer 30 to 40 minutes, stirring, until it turns very dark and the oil separates.","Cool completely and store in a clean dry jar with a layer of oil on top."],
  tip:"Be patient with the onions. The dark flavor of shito comes from slow frying." },
// ---------- SOUTH AFRICA ----------
{ id:"pap", country:"South African", name:"Pap", aka:["pap","mealie pap","uphuthu","stiff pap","pap and meat"], cat:"swallow", level:1, type:"meal", time:"25 min", serves:3,
  ing:["2 cups maize meal","4 cups water","1/2 tsp salt","Optional: a knob of butter"],
  steps:["Boil the water with the salt.","Lower the heat. Add the maize meal in a steady stream while stirring.","Cover and cook on low heat 15 minutes.","Stir with a wooden spoon, pressing out lumps. Cook 5 more minutes.","Serve with braai meat, boerewors or chakalaka."],
  tip:"Use less water (about 3 cups) for stiff pap, more for soft porridge-style pap." },
{ id:"chakalaka", country:"South African", name:"Chakalaka", aka:["chakalaka","chakalaka relish"], cat:"sauce", level:1, type:"snack", time:"30 min", serves:5,
  ing:["1 onion, chopped","2 carrots, grated","1 green bell pepper, chopped","1 red bell pepper, chopped","2 tomatoes, chopped","1 can baked beans (optional)","3 garlic cloves","1 tbsp grated ginger","1 to 2 tbsp curry powder","1 chili, chopped","3 tbsp oil","Salt"],
  steps:["Heat the oil and fry the onion until soft.","Add garlic, ginger, chili and curry powder. Fry 1 minute.","Add the carrots and bell peppers. Cook 5 minutes.","Add the tomatoes and salt. Simmer 10 minutes.","Stir in the baked beans and cook 5 more minutes.","Serve warm or cold with pap, braai meat or bread."],
  tip:"It tastes better the next day. Make extra." },
{ id:"bunny-chow", country:"South African", name:"Bunny Chow", aka:["bunny chow","bunny","chicken bunny"], level:2, type:"meal", time:"70 min", serves:4,
  ing:["1 unsliced white loaf, cut in quarters","600 g chicken or lamb","2 onions","3 tomatoes, chopped","2 potatoes, cubed","3 tbsp curry powder","4 garlic cloves","1 tbsp grated ginger","1/4 cup oil","A few curry leaves (optional)","Salt","2 cups water"],
  steps:["Heat the oil and fry the onions until golden.","Add garlic, ginger, curry leaves and curry powder. Fry 2 minutes.","Add the tomatoes and cook until soft. Add the meat and brown it.","Add the water and salt. Simmer 25 minutes, then add the potatoes and cook 15 minutes more until tender.","Hollow out each quarter loaf, keeping the removed bread.","Fill each loaf with curry and top with the bread lid. Eat with your hands."],
  tip:"Use bread with a firm crust, or the curry soaks through and the loaf collapses." },
{ id:"boerewors", country:"South African", name:"Boerewors Roll", aka:["boerewors","braai","braai boerewors","boerie roll","boerewors roll"], level:1, type:"snack", time:"30 min", serves:4,
  ing:["500 g boerewors (coil sausage)","4 hot dog rolls","1 onion, sliced","2 tomatoes, sliced","Chakalaka or tomato relish","Oil"],
  steps:["Heat the grill or a pan to medium. Do not prick the sausage.","Cook the coil, turning once, for 15 to 20 minutes until browned and cooked through.","Fry the onion in a little oil until soft.","Cut the boerewors to size and place in rolls.","Top with onion, tomato and chakalaka."],
  tip:"Keep the heat medium. Hot fire burns the outside before the inside cooks." },
{ id:"bobotie", country:"South African", name:"Bobotie", aka:["bobotie","bobotie and yellow rice"], level:2, type:"meal", time:"80 min", serves:5,
  ing:["500 g beef mince","1 onion, chopped","2 slices white bread","1 cup milk","1 tbsp curry powder","1 tsp turmeric","2 tbsp apricot jam or chutney","1/4 cup raisins","1 tbsp vinegar","2 eggs","3 bay leaves","2 tbsp oil","Salt"],
  steps:["Heat the oven to 180 C. Soak the bread in the milk.","Fry the onion in oil until soft. Add the mince and brown it.","Add curry powder, turmeric, jam, raisins, vinegar and salt.","Squeeze the bread, keeping the milk. Mash the bread and mix into the meat.","Press the mixture into a greased baking dish.","Beat the eggs with the saved milk and pour over the top. Lay the bay leaves on top.","Bake 30 to 35 minutes until the topping is set and golden. Serve with yellow rice."],
  tip:"The sweet and spicy mix is the point. Do not skip the jam or raisins." },
{ id:"potjiekos", country:"South African", name:"Potjiekos", aka:["potjiekos","potjie","potjie stew"], level:3, type:"meal", time:"180 min", serves:6,
  ing:["1 kg lamb or beef chunks","3 onions, sliced","4 carrots, chunked","4 potatoes, halved","1/2 cabbage, in wedges","3 garlic cloves","2 tbsp oil","1 cup beef stock","1 tbsp curry powder or mixed spice","Salt and pepper"],
  steps:["Heat the oil in a heavy pot over medium coals or heat. Brown the meat in batches and set aside.","Fry the onions and garlic until soft. Add the spices.","Return the meat. Add the stock.","Layer the carrots on top, then the potatoes, then the cabbage. Do not stir.","Cover and simmer on low heat about 2 to 2.5 hours until the meat is tender.","Season and serve with pap or rice."],
  tip:"Do not stir. Layers and steam do the work, and stirring turns it to mush." },
{ id:"malva-pudding", country:"South African", name:"Malva Pudding", aka:["malva pudding","malva"], level:2, type:"snack", time:"60 min", serves:6,
  ing:["1 cup sugar","1 egg","1 cup flour","1 tbsp apricot jam","1 tbsp butter, melted","1 tsp baking soda","1 tsp vinegar","1 cup milk","Sauce: 1 cup cream, 1/2 cup butter, 1 cup sugar, 1/2 cup hot water"],
  steps:["Heat the oven to 180 C.","Beat the egg and sugar until pale. Mix in the jam and melted butter.","Stir the baking soda into the vinegar and add to the mix.","Fold in the flour and milk alternately until smooth.","Pour into a greased dish and bake 35 minutes until risen and dark golden.","While it bakes, warm the sauce ingredients until the sugar melts.","Pour the sauce over the hot pudding so it soaks in. Serve with custard or ice cream."],
  tip:"Pour the sauce while the pudding is still hot. It soaks in and makes the sponge sticky and rich." },
{ id:"vetkoek", country:"South African", name:"Vetkoek", aka:["vetkoek","vetkoek and mince","fat cakes","magwinya"], level:2, type:"snack", time:"60 min", serves:4,
  ing:["3 cups flour","2 tsp instant yeast","1 tbsp sugar","1 tsp salt","1.5 cups warm water","Oil for deep frying","Filling: cooked curried mince, cheese or jam"],
  steps:["Mix the flour, yeast, sugar and salt. Add the warm water and mix to a soft sticky dough.","Cover and let rise 30 to 40 minutes until doubled.","Heat 5 cm of oil on medium heat.","Drop in golf-ball-size spoonfuls. Fry 3 to 4 minutes, turning, until deep golden and puffed.","Drain on paper. Split open and fill with mince, cheese or jam."],
  tip:"If the oil is too hot, they brown outside and stay raw inside. Medium heat." },
// ---------- ETHIOPIA ----------
{ id:"injera", country:"Ethiopian", name:"Injera", aka:["injera","enjera","ethiopian bread"], level:3, type:"meal", time:"40 min + 2 days rest", serves:4,
  ing:["2 cups teff flour","2.5 cups water","Pinch of salt","Extra water to thin the batter"],
  steps:["Mix the teff flour and water into a smooth batter in a large bowl.","Cover with a cloth and leave at room temperature for 2 days. It will bubble and smell sour.","Pour off any water on top. Thin the batter with water to a runny pancake consistency. Add the salt.","Heat a non-stick pan on medium heat. Pour in a thin spiral of batter from the outside to the middle.","Cover and cook 2 to 3 minutes until holes form on top and the edges lift. Do not flip.","Cool on a clean cloth. Serve under stews."],
  tip:"Only cook one side. The holey top soaks up the stew, and the underside stays smooth." },
{ id:"misir-wot", country:"Ethiopian", name:"Misir Wot (Red Lentil Stew)", aka:["misir wot","misir wat","red lentil stew","ethiopian lentils"], level:2, type:"meal", time:"45 min", serves:4,
  ing:["1.5 cups red lentils, rinsed","2 onions, finely chopped","1/4 cup oil","3 garlic cloves, minced","1 tbsp grated ginger","2 tbsp berbere spice","1 tbsp tomato paste","3 cups water","Salt"],
  steps:["Cook the chopped onions in a dry pot on medium heat for 8 to 10 minutes, stirring, until soft and lightly browned.","Add the oil, garlic and ginger. Cook 2 minutes.","Add the berbere and tomato paste. Cook 3 minutes.","Add the lentils, water and salt.","Simmer 20 to 25 minutes, stirring, until the lentils are soft and thick.","Serve with injera or rice."],
  tip:"Cooking the onions dry first builds the thick base. Add water if it sticks." },
{ id:"shiro-wot", country:"Ethiopian", name:"Shiro Wot", aka:["shiro","shiro wot","shiro wat","chickpea stew"], level:2, type:"meal", time:"35 min", serves:4,
  ing:["1/2 cup shiro powder (or chickpea flour with 1 tbsp berbere)","2 onions, finely chopped","3 tbsp oil","3 garlic cloves","1 tbsp berbere","3 cups water","Salt"],
  steps:["Cook the onions in a pot without oil for 6 minutes until soft.","Add the oil, garlic and berbere. Cook 3 minutes.","Whisk the shiro powder into the water until smooth with no lumps.","Pour into the pot while stirring.","Simmer on low heat 15 to 20 minutes, stirring often, until thick and glossy.","Salt to taste and serve with injera."],
  tip:"Whisk the powder into cold water first. Adding it dry to the pot makes lumps." },
{ id:"doro-wot", country:"Ethiopian", name:"Doro Wot", aka:["doro wot","doro wat","ethiopian chicken stew"], level:3, type:"meal", time:"150 min", serves:5,
  ing:["8 chicken drumsticks or thighs","4 large onions, finely chopped","1/3 cup berbere spice","1/2 cup butter or niter kibbeh (spiced butter)","4 garlic cloves","1 tbsp grated ginger","2 cups water","4 hard-boiled eggs, peeled","Juice of 1 lemon","Salt"],
  steps:["Wash the chicken in water and lemon juice and drain.","Cook the onions in a dry heavy pot on medium-low heat for 25 to 30 minutes, stirring, until very soft and reduced.","Add the butter, garlic and ginger. Cook 5 minutes.","Add the berbere. Cook 10 minutes, stirring, so it does not burn.","Add the chicken, water and salt. Simmer covered 45 minutes until tender.","Score the eggs lightly and add them. Simmer 10 more minutes.","Serve with injera."],
  tip:"The onions are the sauce. Do not rush them." },
{ id:"tibs", country:"Ethiopian", name:"Tibs", aka:["tibs","beef tibs","derek tibs"], level:2, type:"meal", time:"30 min", serves:3,
  ing:["500 g beef, in bite-size cubes","1 onion, sliced","2 tbsp butter or oil","3 garlic cloves","1 green chili, sliced","1 tomato, chopped","1 sprig rosemary","1/2 tsp berbere (optional)","Salt and pepper"],
  steps:["Heat the pan until very hot. Add the butter and the beef.","Fry the beef on high heat, stirring, for 5 to 6 minutes until browned.","Add the onion, garlic and chili. Cook 3 minutes.","Add the tomato, rosemary and berbere. Cook 3 more minutes.","Season and serve with injera or bread."],
  tip:"Do not crowd the pan. Fry in two batches if needed so the meat browns instead of steaming." },
{ id:"atkilt-wot", country:"Ethiopian", name:"Atkilt Wot", aka:["atkilt wot","atkilt","cabbage carrot potato stew"], level:1, type:"meal", time:"40 min", serves:4,
  ing:["1/2 head cabbage, chopped","3 carrots, sliced","3 potatoes, cubed","1 onion, sliced","3 garlic cloves","1 tbsp grated ginger","1 tsp turmeric","3 tbsp oil","1/2 cup water","Salt and pepper"],
  steps:["Fry the onion in oil until soft. Add garlic, ginger and turmeric.","Add the potatoes and carrots with the water and salt. Cover and cook 10 minutes.","Add the cabbage. Stir.","Cover and cook 15 minutes until everything is tender.","Add pepper and serve with injera or rice."],
  tip:"Use only a little water. The vegetables steam in their own juice." },
// ---------- UGANDA ----------
{ id:"rolex", country:"Ugandan", name:"Rolex", aka:["rolex","ugandan rolex","egg chapati roll"], level:1, type:"snack", time:"15 min", serves:2,
  ing:["2 chapatis (see recipe)","3 eggs","1/4 cabbage, finely sliced","1 tomato, chopped","1/2 onion, chopped","2 tbsp oil","Salt and pepper"],
  steps:["Beat the eggs with the cabbage, tomato, onion, salt and pepper.","Heat the oil in a pan. Pour in the egg mix and make a thin omelette.","Warm the chapatis on a dry pan.","Place the omelette on the chapati and roll up tightly.","Eat hot."],
  tip:"The name comes from 'rolled eggs'. Slice the cabbage thin so it cooks inside the omelette." },
{ id:"matoke", country:"Ugandan", name:"Matoke", aka:["matoke","matooke","mashed green bananas"], level:2, type:"meal", time:"70 min", serves:4,
  ing:["8 green cooking bananas (matoke)","Banana leaves (or foil)","Water","Salt","To serve: groundnut sauce, beef stew or beans"],
  steps:["Peel the bananas under water or with oiled hands to avoid staining. Keep them in water.","Line a pot with banana leaves. Add the bananas and 1 cup of water.","Cover with more leaves and a lid. Steam on low heat 45 to 60 minutes until soft.","Mash in the leaves with a wooden spoon or by hand through the leaf until smooth.","Serve with groundnut sauce or stew."],
  tip:"Choose firm, green bananas. Ripe ones will be sweet and mushy instead of starchy." },
{ id:"ugandan-groundnut-sauce", country:"Ugandan", name:"Groundnut Sauce (Ebinyebwa)", aka:["groundnut sauce","ebinyebwa","peanut sauce"], cat:"sauce", level:2, type:"meal", time:"40 min", serves:4,
  ing:["1 cup roasted peanuts, ground (or 1/2 cup peanut paste)","1 onion, chopped","2 tomatoes, chopped","2 tbsp oil","2 cups water","Salt","Optional: smoked fish or dried mushrooms"],
  steps:["Fry the onion in oil until soft. Add the tomatoes and cook 5 minutes.","Mix the ground peanuts with a little cold water into a smooth paste.","Add the remaining water to the pot, then stir in the peanut paste.","Add salt and fish or mushrooms if using.","Simmer on low heat 20 minutes, stirring, until thick and the oil rises.","Serve with matoke, sweet potatoes or posho."],
  tip:"Mix the peanut paste with cold water before adding it. Hot water makes it clump." },
{ id:"luwombo", country:"Ugandan", name:"Luwombo", aka:["luwombo","luwombo stew","steamed banana leaf stew"], level:3, type:"meal", time:"150 min", serves:4,
  ing:["600 g chicken or beef, in pieces","2 tomatoes, chopped","1 onion, chopped","2 tbsp groundnut paste","1/2 cup water or stock","Salt","Banana leaves (or foil)","String"],
  steps:["Wilt the banana leaves briefly over a flame or hot water so they bend without tearing.","Mix the meat with the tomato, onion, groundnut paste, salt and water.","Place a portion in the middle of a leaf. Fold the leaf into a tight parcel and tie with string.","Stack the parcels in a pot on a bed of leaves. Add a little water.","Steam on low heat 1.5 to 2 hours, topping up water as needed.","Open at the table and serve with matoke or rice."],
  tip:"Wrap tightly so none of the juice escapes. That sealed steam is what makes it tender." },
{ id:"kikomando", country:"Ugandan", name:"Chapati and Beans (Kikomando)", aka:["kikomando","chapati and beans","chapo and beans","chapati beans"], level:1, type:"meal", time:"20 min", serves:2,
  ing:["3 chapatis (see recipe)","2 cups cooked beans stew","1 onion, chopped","1 tomato, chopped","Oil, salt, chili (optional)"],
  steps:["Fry the onion and tomato in a little oil for 3 minutes.","Add the cooked beans and warm through for 5 minutes.","Cut the chapatis into strips or small pieces.","Pour the hot beans over the chapati pieces and mix.","Eat from the plate or bowl."],
  tip:"Make it with day-old chapati. It soaks up the beans without falling apart." },
// ---------- TANZANIA ----------
{ id:"zanzibar-pizza", country:"Tanzanian", name:"Zanzibar Pizza", aka:["zanzibar pizza","zanzibar mix pizza"], level:2, type:"snack", time:"45 min", serves:3,
  ing:["2 cups flour","1/2 cup water","2 tbsp oil","1 tsp salt","200 g minced beef, cooked and seasoned","3 eggs","1 onion, finely chopped","1 tomato, chopped","1/2 cup cheese (optional)","Extra oil for frying"],
  steps:["Mix flour, water, 2 tbsp oil and salt into a soft dough. Rest 15 minutes.","Cook the mince with a little onion until dry and seasoned. Mix with the rest of the onion and tomato.","Roll a piece of dough very thin, until you can almost see through it.","Place the mince mixture in the middle with a cracked egg and a little cheese. Fold the sides over to make a square parcel.","Fry in a hot oiled pan 3 to 4 minutes per side until golden and the egg is cooked.","Serve hot."],
  tip:"Roll the dough paper-thin. Thick dough stays raw in the middle." },
{ id:"chipsi-mayai", country:"Tanzanian", name:"Chipsi Mayai", aka:["chipsi mayai","chips mayai","chips omelette","chips and eggs"], level:1, type:"meal", time:"20 min", serves:2,
  ing:["3 large potatoes","3 eggs","Oil for frying","1/2 tsp salt","Pinch of pepper","To serve: kachumbari and tomato sauce"],
  steps:["Peel the potatoes, cut into chips and fry in hot oil until golden. Drain.","Beat the eggs with salt and pepper.","Heat a little oil in a frying pan.","Add the hot chips in an even layer and pour the eggs over.","Cook on medium heat 2 to 3 minutes, flip once, and cook the other side until golden.","Serve with kachumbari."],
  tip:"Put the chips into the pan while hot. They hold together with the egg much better." },
{ id:"mishkaki", country:"Tanzanian", name:"Mishkaki", aka:["mishkaki","beef skewers","meat skewers"], level:2, type:"snack", time:"45 min + marinating", serves:4,
  ing:["500 g beef, cut in 2 cm cubes","1 tbsp ginger-garlic paste","2 tbsp lemon juice","1 tsp paprika","1 tsp cumin","1/2 tsp chili powder","2 tbsp plain yogurt","2 tbsp oil","1 tsp salt","Skewers (soaked in water)"],
  steps:["Mix the ginger-garlic paste, lemon juice, spices, yogurt, oil and salt.","Coat the beef well. Marinate at least 1 hour, or overnight in the fridge.","Thread on skewers.","Grill over medium-hot charcoal 12 to 15 minutes, turning, brushing with leftover marinade early on.","Serve with kachumbari, chapati or chips."],
  tip:"The yogurt tenderizes the meat. Do not marinate longer than overnight." },
{ id:"ndizi-nyama", country:"Tanzanian", name:"Ndizi Nyama", aka:["ndizi nyama","ndizi na nyama","green banana beef stew","plantain beef stew"], level:2, type:"meal", time:"65 min", serves:4,
  ing:["6 green bananas (or plantains), peeled and halved","500 g beef, in chunks","1 onion, chopped","3 tomatoes, chopped","3 garlic cloves","3 tbsp oil","Salt","Fresh coriander"],
  steps:["Boil the beef with a pinch of salt until nearly tender, about 30 minutes. Keep the stock.","Fry the onion in oil until soft. Add garlic and tomatoes. Cook 5 minutes.","Add the beef and about 2 cups of the stock.","Add the bananas. Cover and simmer 20 to 25 minutes until the bananas are soft and the sauce is thick.","Sprinkle with coriander and serve."],
  tip:"Peel green bananas under water or with oiled hands. The sap stains." },
{ id:"vitumbua", country:"Tanzanian", name:"Vitumbua", aka:["vitumbua","rice pancakes","coconut rice pancakes"], level:2, type:"snack", time:"60 min", serves:4,
  ing:["2 cups rice flour","1 cup coconut milk","1/2 cup sugar","1 tsp ground cardamom","1 tsp instant yeast","1 cup warm water","Pinch of salt","Oil for the pan"],
  steps:["Mix the flour, sugar, cardamom, yeast and salt.","Add the warm water and coconut milk. Whisk to a thick pancake batter.","Cover and let rest 30 to 40 minutes until bubbly.","Heat a pan with round dips (or a small non-stick pan). Add a few drops of oil in each dip.","Fill each dip two-thirds with batter. Cover and cook on medium heat 3 minutes.","Flip and cook until golden on both sides. Serve warm with tea."],
  tip:"Keep the heat medium. They should puff up and brown without burning." },
// ---------- SENEGAL ----------
{ id:"thieboudienne", country:"Senegalese", name:"Thieboudienne", aka:["thieboudienne","thieb","ceebu jen","tiebou dienne","senegalese fish and rice"], cat:"rice", level:3, type:"meal", time:"110 min", serves:6,
  ing:["1 kg firm white fish (tilapia or grouper), cut in steaks","3 cups long-grain or broken rice","2 carrots, in chunks","2 potatoes or 1 cassava, in chunks","1/2 cabbage, in wedges","1 eggplant, halved","2 onions","3 tbsp tomato paste","2 tomatoes","1 bunch parsley","4 garlic cloves","1 scotch bonnet","1/2 cup oil","Salt and stock cubes"],
  steps:["Blend the parsley, garlic, half the onion, scotch bonnet, salt and stock cube into a paste. Stuff it into slits cut in the fish.","Fry the fish in hot oil until golden. Set aside.","In the same oil, fry the remaining onion. Add the tomato paste and tomatoes and fry 10 minutes.","Add 6 cups of water. Boil, then add the carrots, potatoes, cabbage and eggplant. Cook 20 to 25 minutes. Remove the vegetables.","Return the fish to the broth for 5 minutes, then remove it.","Add the washed rice to the broth. Cook covered, on low heat, about 20 minutes until done.","Serve the rice on a big dish topped with fish and vegetables."],
  tip:"The rice cooks in the fish broth. That is where the flavor comes from." },
{ id:"yassa-poulet", country:"Senegalese", name:"Yassa Poulet", aka:["yassa","yassa poulet","chicken yassa","senegalese chicken"], level:2, type:"meal", time:"80 min + marinating", serves:4,
  ing:["1 kg chicken pieces","6 onions, sliced","1/2 cup lemon juice","2 tbsp Dijon mustard","4 garlic cloves","1 scotch bonnet","1/3 cup oil","1 cup water or stock","2 bay leaves","Salt and pepper"],
  steps:["Mix the lemon juice, mustard, garlic, half the onions, salt and pepper. Coat the chicken and marinate at least 2 hours.","Remove the chicken from the marinade, keeping the onions. Brown the chicken in oil or grill it. Set aside.","In the same pot, cook the marinade onions and remaining onions on low heat 15 minutes until soft.","Add the water, bay leaves and the scotch bonnet. Return the chicken.","Simmer 25 to 30 minutes until the chicken is tender and the sauce is thick.","Serve with white rice."],
  tip:"Use a lot of onions. They melt into the sauce." },
{ id:"mafe", country:"Senegalese", name:"Mafe (Peanut Stew)", aka:["mafe","maafe","peanut stew","groundnut stew"], level:2, type:"meal", time:"90 min", serves:5,
  ing:["500 g beef or lamb, in chunks","1/2 cup peanut butter (unsweetened)","1 onion, chopped","2 tbsp tomato paste","2 tomatoes, chopped","1 sweet potato, cubed","2 carrots, chunked","1/4 cabbage, in pieces","1 scotch bonnet","3 tbsp oil","3 cups stock or water","Salt"],
  steps:["Brown the meat in oil. Remove it.","Fry the onion until soft. Add the tomato paste and tomatoes. Cook 8 minutes.","Return the meat with the stock. Simmer 30 to 40 minutes.","Mix the peanut butter with a little hot stock until smooth. Stir it in.","Add the sweet potato, carrots, cabbage and scotch bonnet whole. Simmer 20 to 25 minutes until tender.","Serve with rice."],
  tip:"Add the scotch bonnet whole for flavor without too much heat. Remove it before serving if you like." },
{ id:"dibi", country:"Senegalese", name:"Dibi", aka:["dibi","dibi hausa","grilled lamb senegal"], level:2, type:"meal", time:"50 min", serves:3,
  ing:["600 g lamb chops or beef strips","2 tbsp Dijon mustard","3 tbsp oil","1 tsp black pepper","1 tsp salt","2 onions, sliced","1 tbsp lemon juice","Bread to serve"],
  steps:["Rub the meat with salt, pepper and 1 tbsp oil.","Grill over hot coals or a very hot pan for 4 to 6 minutes per side until browned.","Meanwhile, fry the onions in the remaining oil until soft. Stir in the mustard and lemon juice.","Chop the meat and serve with the onion sauce, extra pepper and bread."],
  tip:"Serve it hot straight from the grill, with a bit of the charred edge." },
// ---------- MOROCCO ----------
{ id:"chicken-tagine", country:"Moroccan", name:"Chicken Tagine", aka:["chicken tagine","tagine","moroccan tagine","chicken olive tagine"], level:2, type:"meal", time:"90 min", serves:4,
  ing:["1 kg chicken pieces","2 onions, sliced","4 garlic cloves","1 tsp ground ginger","1 tsp turmeric","1 tsp cumin","1 tsp paprika","1/2 tsp cinnamon","1 preserved lemon, rind sliced (or juice of 1 lemon)","1 cup green olives","1/4 cup chopped coriander and parsley","3 tbsp olive oil","1 cup water","Salt and pepper"],
  steps:["Mix the garlic, spices, salt and 1 tbsp of oil. Rub on the chicken and rest 30 minutes.","Heat the remaining oil in a wide pot. Cook the onions on low heat 10 minutes.","Add the chicken and the water. Cover and simmer on low heat 45 minutes.","Add the preserved lemon, olives and herbs. Cook uncovered 15 minutes until the sauce is thick.","Serve with bread or couscous."],
  tip:"If you cannot find preserved lemon, use fresh lemon juice and zest near the end." },
{ id:"couscous-vegetables", country:"Moroccan", name:"Couscous with Vegetables", aka:["couscous","moroccan couscous","couscous with vegetables"], level:3, type:"meal", time:"100 min", serves:5,
  ing:["2 cups couscous","600 g lamb or chicken","2 onions","2 carrots","2 zucchini","1/4 pumpkin or butternut, chunked","1 cup cooked chickpeas","2 tomatoes","1 tsp ginger","1 tsp turmeric","1 tbsp ras el hanout","3 tbsp oil","2 tbsp butter","Salt","Water"],
  steps:["Brown the meat with onions and oil in a large pot. Add the spices, tomatoes and 5 cups of water. Simmer 40 minutes.","Add the carrots, pumpkin and chickpeas. Cook 15 minutes. Add the zucchini for the last 10 minutes.","Put the couscous in a bowl. Pour over 2 cups of hot salted water, cover for 5 minutes.","Fluff with a fork, adding the butter. Break up lumps.","Pile the couscous on a dish and top with the meat and vegetables. Ladle the broth on the side."],
  tip:"Fluff the couscous with a fork, never stir with a spoon. It keeps the grains light." },
{ id:"harira", country:"Moroccan", name:"Harira", aka:["harira","moroccan soup","moroccan lentil soup"], cat:"soup", level:2, type:"meal", time:"65 min", serves:5,
  ing:["1/2 cup lentils","1/2 cup cooked chickpeas","1 onion, chopped","3 tomatoes, grated","1 celery stick, chopped","1 tbsp tomato paste","1/3 cup vermicelli","150 g beef, diced (optional)","1 tsp ginger","1 tsp turmeric","1/2 tsp cinnamon","1/2 tsp pepper","Fresh coriander and parsley","2 tbsp oil","6 cups water","Lemon wedges","Salt"],
  steps:["Fry the onion and beef in oil until soft.","Add the celery, spices, grated tomatoes and tomato paste. Cook 5 minutes.","Add the lentils and water. Simmer 30 minutes.","Add the chickpeas and vermicelli. Cook 10 more minutes.","Add the herbs and salt.","Serve hot with lemon wedges and dates or bread."],
  tip:"It is traditionally eaten to break the fast in Ramadan, but it is a good meal any day." },
{ id:"zaalouk", country:"Moroccan", name:"Zaalouk", aka:["zaalouk","eggplant salad","moroccan eggplant dip","aubergine salad"], level:2, type:"snack", time:"45 min", serves:4,
  ing:["2 eggplants, peeled and cubed","4 tomatoes, grated","3 garlic cloves, minced","1 tsp paprika","1 tsp cumin","3 tbsp olive oil","1/4 cup chopped coriander","Juice of 1/2 lemon","Salt"],
  steps:["Steam or boil the eggplant for 15 minutes until soft. Drain well and mash.","Heat the oil in a pan. Add garlic, paprika and cumin. Cook 30 seconds.","Add the grated tomato. Cook 10 minutes until thick.","Add the eggplant and cook 10 minutes, mashing, until thick and jammy.","Stir in the coriander, lemon juice and salt. Serve warm or cold with bread."],
  tip:"Drain the eggplant well. Water makes the dip loose and bland." }
];
